[{"type":"text","text":"===== 苏住房G resolveServerAssetUrl.js =====
/**
 * SPA 部署目录基址（保证尾斜杠）。
 * 例如页面在 https://xxx.com/test/#/xxx 时 pathname 为 /test，
 * 若不补成 /test/，相对解析会把最后一段当文件名替换掉，得到 /zhi2-test 而非 /test/zhi2-test。
 */
function getAssetResolveBase() {
  if (typeof window === 'undefined' || !window.location) return ''
  const { origin, pathname } = window.location
  let dir = pathname || '/'
  if (/\.html?$/i.test(dir)) {
    dir = dir.replace(/[^/]+$/, '')
  } else if (!dir.endsWith('/')) {
    dir = `${dir}/`
  }
  return `${origin}${dir}`
}

/**
 * 从完整 URL 中截取站内资源路径（/zhi2-test、/api、/uploads 等），去掉域名与部署前缀。
 */
function extractSiteAssetPath(absoluteUrl) {
  try {
    const u = new URL(absoluteUrl)
    // zhi2 / zhi2-test / zhi2-dev 等文件前缀；以及 api、uploads、profile
    const match = u.pathname.match(/\/(?:api|zhi2[\w-]*|uploads|profile)(?=\/|$)/)
    if (!match) return ''
    return u.pathname.slice(match.index) + u.search + u.hash
  } catch {
    return ''
  }
}

/**
 * 将后端返回的站内路径转为浏览器可请求的完整 URL。
 * 后端常见返回：/zhi2-test/xxx；部署在域名/test/ 下时应访问 /test/zhi2-test/xxx。
 * 按当前页面部署目录做相对解析，不写死 test。
 * http(s) 绝对地址若含站内资源段，先去掉域名与部署前缀再相对解析。
 * 其余外链、data:、blob:、不以 / 开头的地址原样返回。
 */
export function resolveServerAssetUrl(input) {
  if (input == null || input === '') return ''
  let path = String(input).trim()
  if (!path) return ''

  if (/^(data:|blob:)/i.test(path)) {
    return path
  }

  if (/^(https?:\/\/|\/\/)/i.test(path)) {
    const absolute = path.startsWith('//')
      ? `${typeof window !== 'undefined' && window.location ? window.location.protocol : 'https:'}${path}`
      : path
    const sitePath = extractSiteAssetPath(absolute)
    if (!sitePath) {
      return absolute
    }
    path = sitePath
  }

  if (!path.startsWith('/')) {
    return path
  }

  if (path.startsWith('/@') || path.startsWith('/src/')) {
    return path
  }

  const base = getAssetResolveBase()
  if (!base) {
    return path
  }

  const relative = path.replace(/^\/+/, '')
  try {
    return new URL(relative, base).href
  } catch {
    return path
  }
}

/**
 * 将相对资源路径转为可访问 URL，不拼接 VITE_APP_BASE_API（如 /api/v2.0）。
 * 站内路径按当前页面部署目录解析（/test/、/sz/ 等自动带上前缀）。
 */
export function resolvePublicAssetUrl(url) {
  if (url == null || url === '') return ''
  const s = String(url).trim()
  if (!s) return ''
  if (/^(data:|blob:)/i.test(s)) {
    return s
  }
  const path = /^(https?:\/\/|\/\/)/i.test(s) || s.startsWith('/') ? s : `/${s}`
  return resolveServerAssetUrl(path)
}

