function sanitizeSvg(code) {
  let s = code.replace(/<\?xml[\s\S]*?\?>/gi, '').replace(/<!DOCTYPE[\s\S]*?>/gi, '');
  s = s.replace(/<\/([a-zA-Z][\w:-]*)>\s*<\/\1>/g, '</$1>');
  return s;
}

for (const file of svgFiles) {
